import re
import hashlib
import datetime
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_order_lines(order_id: str, order_number: str) -> list[dict[str, Any]]:
    found = [r for r in od_rows("od_order_lines", order_number) if order_id in od_link_ids(r, "order")]
    if not found:
        found = [r for r in od_rows("od_order_lines") if order_id in od_link_ids(r, "order")]
    found.sort(key=lambda r: float(od_data(r).get("line_number") or 0))
    return found


def od_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()


def od_settings() -> dict[str, Any]:
    out: dict[str, Any] = {"care": "everything"}
    try:
        saved = dict(api.extension.settings() or {})
    except Exception:
        saved = {}
    for key, value in saved.items():
        if value is not None and value != "":
            out[key] = value
    return out


def od_stamp(lines: list[dict[str, Any]]) -> str:
    parts = ["%d:%s:%.3f:%s" % (int(x["line_number"]), x["item_code"], float(x["quantity"]), x["unit"]) for x in lines]
    return hashlib.sha1("|".join(parts).encode("utf-8")).hexdigest()


def as_number(value: Any) -> float:
    try:
        return float(re.sub(r"[^0-9.\-]", "", str(value)) or 0)
    except ValueError:
        return 0.0


order_id = params["order_id"]
found = api.records.get(type_slug="od_orders", record_id=order_id) or {}
order: dict[str, Any] = dict(found.get("record") or {})
if not order:
    raise ValueError("No order has this id. Pass the order_id that 'register order' returned.")
d = od_data(order)
stage = od_text(order.get("stage"))
order_number = od_text(order.get("title"))
handover: dict[str, Any] = {}
released = False
if stage == "released":
    released = True
    result = "Order " + order_number + " was already released."
else:
    care = od_text(od_settings().get("care")) or "everything"
    rows = od_order_lines(order_id, order_number)
    now_lines: list[dict[str, Any]] = []
    marked = 0
    for row in rows:
        line = od_data(row)
        if line.get("needs_review"):
            marked += 1
        now_lines.append({"line_number": int(as_number(line.get("line_number"))), "item_code": od_text(line.get("item_code")), "quantity": as_number(line.get("quantity")), "unit": od_text(line.get("unit"))})
    why = ""
    if care not in ("problems", "hands_off"):
        why = "the manager chose to approve every order"
    elif stage != "confirmed" or not d.get("auto_confirmed") or od_text(d.get("recommended_outcome")) != "ready":
        why = "the last check did not clear it to go through without a person"
    elif not now_lines:
        why = "it has no lines"
    elif marked:
        why = str(marked) + (" line is" if marked == 1 else " lines are") + " marked for a person to check"
    elif list(d.get("flags") or []):
        why = "the order has a flag"
    elif not od_text(d.get("check_stamp")) or od_text(d.get("check_stamp")) != od_stamp(now_lines):
        why = "its lines changed after it was checked"
    if why:
        result = "Not released. Order " + order_number + " needs a person because " + why + ". Ask the reviewer with 'release to warehouse'."
    else:
        lines = []
        for row in rows:
            line = od_data(row)
            if not od_text(line.get("item_code")):
                continue
            lines.append({"line_number": line.get("line_number"), "item_code": od_text(line.get("item_code")), "quantity": line.get("quantity"), "unit": od_text(line.get("unit")), "note": od_text(line.get("line_note"))})
        handover = {
            "order_number": order_number,
            "account_code": od_text(d.get("account_code")),
            "po_number": od_text(d.get("po_number")),
            "delivery_date": od_text(d.get("delivery_date")),
            "delivery_address": od_text(d.get("delivery_address_raw")),
            "lines": lines,
        }
        api.records.update(type_slug="od_orders", record_id=order_id, record={"data": {"released_on": od_now()}})
        api.records.change_stage(type_slug="od_orders", record_id=order_id, stage="released", note="Released to the warehouse without a person: every check passed")
        released = True
        result = "Order " + order_number + " was released to the warehouse."
